  echo "check-changelog: these files under src/ changed since ${base} and CHANGELOG.md did not:"
  printf '%s\n' "$src_changed" | sed 's/^/  /'
  echo
  echo "Add an entry under ## [Unreleased], written for somebody installing the package."
